<script setup lang="ts">
import {computed,ref} from 'vue';
import {formatGradient,gradientText,type TextFormat} from './color-text';
const text=ref('三秋叶，下一场冒险'),start=ref('#f3b567'),end=ref('#42d9c8'),format=ref<TextFormat>('tellraw'),notice=ref('');
const result=computed(()=>{try{return {spans:gradientText(text.value,start.value,end.value),output:formatGradient(text.value,start.value,end.value,format.value),error:''};}catch(e){return {spans:[],output:'',error:e instanceof Error?e.message:'文字无效'};}});
async function copy(){try{await navigator.clipboard.writeText(result.value.output);notice.value='已复制，未向游戏发送命令。';}catch{notice.value='未能复制，请选中输出文本手动复制。';}}
</script>
<template><section class="tool-card" aria-label="游戏彩字生成器"><header><h2>游戏彩字</h2><p>预览渐变，选择游戏或插件支持的格式，再复制使用。</p></header><label>文字<input v-model="text" maxlength="1024" data-gradient-text/></label><div class="tool-inline"><label>起始颜色<input v-model="start" type="color" data-gradient-start/></label><label>结束颜色<input v-model="end" type="color" data-gradient-end/></label><label>输出格式<select v-model="format" data-gradient-format><option value="tellraw">原版 Java · /tellraw</option><option value="minimessage">MiniMessage · 需要插件支持</option><option value="legacy">传统 &amp; · 16色</option></select></label></div><p v-if="result.error" role="alert">{{result.error}}</p><div class="gradient-preview" aria-label="彩字预览"><span v-for="(s,i) in result.spans" :key="i" :style="{color:s.color}">{{s.text}}</span></div><label>输出<textarea :value="result.output" readonly rows="5" data-gradient-output/></label><button class="launcher-primary" :disabled="!!result.error||!text" data-gradient-copy @click="copy">复制彩字</button><p role="status">{{notice}}</p><p class="launcher-caption">/tellraw 需要命令权限，适用支持十六进制文字组件的 Java 版（1.16及以后）；不会自动发送。MiniMessage 与 &amp; 颜色仅在对应插件中使用。原版普通聊天不支持直接粘贴这些颜色代码。</p></section></template>
<style scoped>.tool-card{padding:24px}.tool-card label{display:grid;gap:9px;margin:16px 0}.tool-card input:not([type=color]),.tool-card textarea,.tool-card select{padding:12px;background:#14221e;color:inherit;border:1px solid #78978a66;border-radius:8px;max-width:100%;min-width:0}.tool-inline{display:flex;gap:20px;flex-wrap:wrap}.gradient-preview{font-size:28px;padding:24px;background:#0b1211;border:1px solid #78978a33;border-radius:12px;min-height:84px;white-space:pre-wrap;overflow-wrap:anywhere}.tool-card textarea{resize:vertical;white-space:pre-wrap;font-family:monospace}.tool-card p{line-height:1.7}</style>
